6	export type CreateBusinessState = { error: string | null };
7	
8	export async function createBusiness(
9	  _prevState: CreateBusinessState,
10	  formData: FormData,
11	): Promise<CreateBusinessState> {
12	  const supabase = await createClient();
13	  const {
14	    data: { user },
15	  } = await supabase.auth.getUser();
16	
17	  if (!user) {
18	    redirect("/login");
19	  }
20	
21	  const name = (formData.get("name") as string)?.trim();
22	  const businessType = formData.get("business_type") as string;
23	
24	  if (!name) {
25	    return { error: "Nama toko wajib diisi." };
26	  }
27	  if (businessType !== "fnb" && businessType !== "retail") {
28	    return { error: "Pilih jenis bisnis dulu." };
29	  }
30	
31	  const { error } = await supabase.from("businesses").insert({
32	    owner_id: user.id,
33	    name,
34	    business_type: businessType,
35	  });
36	
37	  if (error) {
38	    return { error: error.message };
39	  }
40	
41	  redirect("/dashboard");
42	}
