10	function formatRupiah(value: number) {
11	  return `Rp${value.toLocaleString("id-ID")}`;
12	}
13	
14	function formatTime(iso: string) {
15	  return new Date(iso).toLocaleTimeString("id-ID", {
16	    hour: "2-digit",
17	    minute: "2-digit",
18	  });
19	}
20	
21	type SelfOrder = {
22	  id: string;
23	  status: string;
24	  created_at: string;
25	  tables: { name: string } | null;
26	  self_order_items: { name: string; qty: number; price: number; note: string | null }[];
27	};
28	
29	export default async function TablesPage({
30	  params,
31	}: {
32	  params: Promise<{ businessId: string }>;
33	}) {
34	  const { businessId } = await params;
35	  const supabase = await createClient();
36	
37	  const { data: business } = await supabase
38	    .from("businesses")
39	    .select("id, name, business_type")
40	    .eq("id", businessId)
41	    .single();
42	
43	  if (!business || business.business_type !== "fnb") {
44	    notFound();
45	  }
46	
47	  const { data: tables } = await supabase
48	    .from("tables")
49	    .select("id, name, qr_slug")
50	    .eq("business_id", businessId)
51	    .order("name", { ascending: true });
52	
53	  const { data: orderRows } = await supabase
54	    .from("self_orders")
55	    .select(
56	      "id, status, created_at, tables(name), self_order_items(name, qty, price, note)",
57	    )
58	    .eq("business_id", businessId)
59	    .neq("status", "selesai")
60	    .order("created_at", { ascending: true });
61	
62	  const orders = (orderRows ?? []) as unknown as SelfOrder[];
63	
64	  const boundAddTable = addTable.bind(null, businessId);
65	
66	  return (
67	    <div className="w-full max-w-2xl">
68	        <h1 className="text-lg font-bold text-zinc-900">
69	          Meja &amp; Self-Order — {business.name}
70	        </h1>
71	
72	        {/* Order masuk */}
73	        <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
74	          <h2 className="text-sm font-semibold text-zinc-900">Order Masuk</h2>
75	          <p className="mt-1 text-xs text-zinc-500">
76	            Pesanan dari pelanggan yang scan QR meja. Selesaikan pembayarannya di kasir.
77	          </p>
78	
79	          <div className="mt-4 space-y-2">
80	            {orders.length > 0 ? (
81	              orders.map((o) => {
82	                const total = o.self_order_items.reduce(
83	                  (sum, i) => sum + i.price * i.qty,
84	                  0,
85	                );
86	                return (
87	                  <div key={o.id} className="rounded-xl border border-zinc-200 px-4 py-3">
88	                    <div className="flex items-center justify-between">
89	                      <p className="text-sm font-semibold text-zinc-900">
90	                        🪑 {o.tables?.name ?? "Meja terhapus"}
91	                      </p>
92	                      <span
93	                        className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${
94	                          o.status === "baru"
95	                            ? "bg-amber-100 text-amber-700"
96	                            : "bg-sky-100 text-sky-700"
97	                        }`}
98	                      >
99	                        {o.status === "baru" ? "Baru" : "Diproses"}
100	                      </span>
101	                    </div>
102	                    <p className="mt-0.5 text-[11px] text-zinc-400">
103	                      Masuk {formatTime(o.created_at)}
104	                    </p>
105	                    <div className="mt-2 space-y-1">
106	                      {o.self_order_items.map((item, idx) => (
107	                        <div key={idx} className="flex justify-between text-xs text-zinc-600">
108	                          <span>
109	                            {item.qty}× {item.name}
110	                            {item.note && (
111	                              <span className="text-zinc-400"> — {item.note}</span>
112	                            )}
113	                          </span>
114	                          <span className="tabular-nums">
115	                            {formatRupiah(item.price * item.qty)}
116	                          </span>
117	                        </div>
118	                      ))}
119	                    </div>
120	                    <div className="mt-2 flex items-center justify-between border-t border-zinc-100 pt-2">
121	                      <p className="text-xs font-semibold text-zinc-900">
122	                        Total {formatRupiah(total)}
123	                      </p>
124	                      {o.status === "baru" ? (
125	                        <OrderStatusButton
126	                          businessId={businessId}
127	                          orderId={o.id}
128	                          nextStatus="diproses"
129	                          label="Proses"
130	                        />
131	                      ) : (
132	                        <OrderStatusButton
133	                          businessId={businessId}
